// TestZZDumpSpec is a throwaway helper to export the generated OpenAPI JSON for
// CLI client regeneration. It only runs when SPEC_DUMP_OUT is set. Delete this
// file after use.
func TestZZDumpSpec(t *testing.T) {
	out := os.Getenv("SPEC_DUMP_OUT")
	if out == "" {
		t.Skip("set SPEC_DUMP_OUT to dump the OpenAPI spec")
	}
	srv := api.NewServer(api.Config{
		TestMode:    true,
		Mode:        "standalone",
		AuthBaseURL: "https://test.auth.partial.to",
		ConsoleURL:  "https://test.auth.partial.to",
	})
	h := NewHandler(srv)
	req := httptest.NewRequest(http.MethodGet, "/api/v1/openapi.json", nil)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("openapi.json status %d: %s", rec.Code, rec.Body.String())
	}
	if err := os.WriteFile(out, rec.Body.Bytes(), 0o644); err != nil {
		t.Fatalf("write spec: %v", err)
	}
	t.Logf("wrote %d bytes to %s", rec.Body.Len(), out)
}

